// Logos de las webs como PNG en base64 (data URI): renderizan en todos los
// clientes de correo (Gmail, Outlook, etc.), a diferencia del SVG inline.
export interface EmailLogo {
  /** PNG en base64, listo para <img src="...">. */
  dataUri: string;
  width: number;
  height: number;
}

